<script setup lang="ts">
const api=useApi(); const { data: orders, refresh }=await useAsyncData('admin-work-orders',()=>api.request<any[]>('/admin/work-orders').catch(()=>[]))
async function verify(id:string){await api.request(`/admin/work-orders/${id}/verify`,{method:'POST'});await refresh()}
</script>
<template><div><div class="mb-5"><p class="label-mono text-signal-deep">Field operations</p><h1 class="mt-1 font-display text-[32px] tracking-[-.04em]">Work orders.</h1><p class="mt-1 text-[11.5px] text-ink/45">Contractor mobilisation, completion evidence and escrow verification.</p></div><div class="space-y-2"><div v-for="o in orders" :key="o._id" class="a-card flex flex-col gap-3 p-4 md:flex-row md:items-center"><div class="flex-1"><div class="flex items-center gap-2"><p class="font-mono text-[8px] text-ink/30">{{ o._id.slice(-6) }}</p><StatusPill :status="o.status"/></div><p class="mt-1 text-[12px] font-medium">{{ o.scope }}</p><p class="font-mono text-[8px] text-ink/35">Scheduled {{ shortDate(o.scheduledAt) }} · {{ o.completionPhotos?.length || 0 }} photos</p></div><button v-if="o.status==='completed'" class="btn btn-primary !min-h-8 !text-[9px]" @click="verify(o._id)">Verify & release escrow</button><span v-else-if="o.status==='verified'" class="font-mono text-[8px] uppercase text-mint-deep">Verified</span></div></div></div></template>
